mapper.select:
SELECT plan_id, user_id, total_time_input, start_location, created_at, status
FROM quick_plan
WHERE plan_id = #{planId}

SELECT plan_id, user_id, total_time_input, start_location, created_at, status
FROM quick_plan
WHERE user_id = #{userId}
AND status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
ORDER BY created_at DESC

mapper.update:
UPDATE quick_plan
SET total_time_input = #{totalTimeInput},
    start_location = #{startLocation},
    status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
WHERE plan_id = #{planId}

UPDATE quick_plan
SET status = #{status, typeHandler=org.apache.ibatis.type.EnumTypeHandler}
WHERE plan_id = #{planId}
